1	// Differential runner: compares /output/test15.mjs against the Python executable.
2	// Usage:
3	//   node diff_vectors.mjs            # replay /workspace/harness/vectors.json (stdout+code)
4	//   node diff_cli.mjs                # replay /workspace/harness/cli_cases.json (stdout+stderr+code)
5	//   node diff_fuzz.mjs [n] [seed]    # fresh random cases, live-compare both programs
6	import { execFileSync } from 'node:child_process';
7	
8	export const EXE = '/workspace/dataset/test15_executable';
9	export const JS = '/output/test15.mjs';
10	
11	// Run a program with the given argv. Byte-exact capture via latin1.
12	// rawArgs: array of strings OR array of Buffers (Buffers let us send invalid UTF-8).
13	export function run(cmd, args, argv, env) {
14	  try {
15	    const stdout = execFileSync(cmd, [...args, ...argv], {
16	      encoding: 'latin1',
17	      stdio: ['ignore', 'pipe', 'pipe'],
18	      maxBuffer: 1 << 24,
19	      env: { ...process.env, ...(env || {}) },
20	    });
21	    return { stdout, stderr: '', code: 0 };
22	  } catch (e) {
23	    if (e.code === 'ENOENT') throw e;
24	    return {
25	      stdout: String(e.stdout ?? ''),
26	      stderr: String(e.stderr ?? ''),
27	      code: e.status === null || e.status === undefined ? -1 : e.status,
28	    };
29	  }
30	}
31	
32	export const runPy = (argv, env) => run(EXE, [], argv, env);
33	export const runJs = (argv, env) => run('node', [JS], argv, env);
34	
35	// Normalizes the parts of stderr that cannot be reproduced byte-for-byte:
36	//   - the PyInstaller pid: "[PYI-1234:ERROR]"  -> "[PYI-PID:ERROR]"
37	//   - the program name emitted by argparse (test15_executable vs test15.mjs)
38	export function normalizeStderr(s) {
39	  return s
40	    .replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]')
41	    .replace(/\btest15_executable\b/g, '<prog>')
42	    .replace(/\btest15\.mjs\b/g, '<prog>');
43	}
44	
45	export function report(name, failures, total) {
46	  const pass = total - failures.length;
47	  console.log(`\n[${name}] ${pass}/${total} passed, ${failures.length} failed`);
48	  for (const f of failures.slice(0, 20)) {
49	    console.log('--------------------------------------------------');
50	    console.log('argv    : ' + JSON.stringify(f.argv));
51	    console.log('field   : ' + f.field);
52	    console.log('expected: ' + JSON.stringify(f.expected));
53	    console.log('actual  : ' + JSON.stringify(f.actual));
54	  }
55	  if (failures.length > 20) console.log(`... and ${failures.length - 20} more`);
56	  return failures.length === 0;
57	}
